155	        (void) metadata;
156	        (void) supplied;
157	        return (validateNative<I>(metadata,
158	                    static_cast<RawNumberT<std::tuple_element_t<I, Arguments>>>(
159	                        std::get<I>(supplied))) && ...);
160	    }

