#include <cstdio>
#include <cstring>
using namespace telemetry;
enum class Mode : std::uint16_t { Off, Auto, Manual };
Mode mode = Mode::Auto;
constexpr auto readMode = +[]() noexcept { return mode; };
constexpr auto writeMode = +[](Mode value) noexcept {
    mode = value;
    return WriteResult::Applied;
};
